#   table    a Surface+Impassable static whose top is the row z
import json, sys, os, collections
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
import sys as _sys
_sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sosbase as B
import hw_gen as gen
import p678_extra as X
ONLY = set(_sys.argv[1:]) or {'new-haven'}

HERE = os.path.dirname(os.path.abspath(__file__))
rows = [r for r in json.load(open(os.path.join(HERE, 'hw-placement.json'))) if r['bank'] in ONLY]
A = B.art()
banks = {}
for spec in gen.BANKS: banks[spec['key']] = spec
built = {}
bad = 0
seen_keys = set(); seen_tiles = set()
out = ['| key | facet | x,y,z | item | mode | why | check |', '|---|---|---|---|---|---|---|']
counts = collections.Counter()
for r in rows:
    errs = []
    spec = banks.get(r['bank'])
    if spec is None: errs.append('unknown bank')
    bank = built.get(r['bank'])
    if bank is None and spec:
        bank = built[r['bank']] = gen.Bank(spec)
    F = bank.F if bank else None
    x, y, z, item, mode = r['x'], r['y'], r['z'], r['itemId'], r['mode']
    if r['facet'] not in B.FACET: errs.append('facet')
    if r['key'] in seen_keys: errs.append('duplicate key')
    if (r['facet'], x, y, item) in seen_tiles: errs.append('duplicate tile and item')
    seen_keys.add(r['key']); seen_tiles.add((r['facet'], x, y, item))
    if not (0 < item < 0x10000) or A.static(item) is None or not B.iname(item): errs.append('no stock art/tiledata for 0x%04X' % item)
    if bank:
        if (x, y) in bank.protected: errs.append('protected: ' + '; '.join(sorted(set(bank.protected[(x, y)]))))
        imp = bool(B.iflags(item) & B.IMP)
        if mode == 'outside':
            s = F.top_surface(x, y, z + 2)
