            if F.blocked(x, y, z): errs.append('blocked by ' + F.blocked(x, y, z))
            if bank.open:
                if (x, y) not in bank.rim(): errs.append('not a platform rim tile')
            else:
                if (x, y) in bank.interior: errs.append('inside')
                if (x, y - 1) not in bank.structure and (x - 1, y) not in bank.structure: errs.append('not south or east of a wall (hidden face)')
