print('%d rows, %d failing, %d banks' % (len(rows), bad, len(built)))
perbank = collections.defaultdict(dict)
for (b, m), n in counts.items(): perbank[b][m] = n
for b in perbank: print('  %-16s %s' % (b, ', '.join('%s %d' % (m, n) for m, n in sorted(perbank[b].items()))))
